"""Find when a cron schedule next fires.

An expression has five whitespace-separated fields: minute (0-59), hour
(0-23), day of month (1-31), month (1-12), and day of week (0-7, where both
0 and 7 are Sunday). Each field is a comma-separated list of items, where
an item is:

- ``*``, every value in the field's range,
- a value ``N``,
- a range ``A-B`` (inclusive, with ``A <= B``),
- any of those followed by ``/S`` for every ``S``-th value starting at the
  first one (``*/15`` in the minute field is 0, 15, 30, 45; ``10-30/10`` is
  10, 20, 30; ``5/20`` is 5, 25, 45, i.e. from 5 to the end of the range).

Months may also be given by the names ``JAN``-``DEC`` and days of the week
by ``SUN``-``SAT``, in any case, including in ranges. A value outside its
field's range, a malformed item, or a field count other than five raises
``ValueError``.

As in Vixie cron, when both the day-of-month and day-of-week fields are
restricted (neither is exactly ``*``), a day matches if it matches either
one; otherwise it must match both.

Times are naive datetimes. ``next_run`` returns the earliest matching time
strictly after ``after``, with seconds and microseconds zero. If nothing
matches within the next five years (e.g. ``0 0 30 2 *``), it raises
``ValueError``.
"""

from __future__ import annotations

import re
from datetime import date, datetime, time, timedelta

_NUMBER_RE = re.compile(r"[0-9]+")

_MONTH_NAMES = {
    name: index + 1
    for index, name in enumerate(
        (
            "JAN",
            "FEB",
            "MAR",
            "APR",
            "MAY",
            "JUN",
            "JUL",
            "AUG",
            "SEP",
            "OCT",
            "NOV",
            "DEC",
        )
    )
}

_DAY_NAMES = {
    name: index
    for index, name in enumerate(
        ("SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT")
    )
}


def _parse_value(token: str, low: int, high: int, names: dict[str, int] | None) -> int:
    upper = token.upper()
    if names is not None and upper in names:
        value = names[upper]
    else:
        if _NUMBER_RE.fullmatch(token) is None:
            raise ValueError(f"invalid value: {token!r}")
        value = int(token)

    if value < low or value > high:
        raise ValueError(f"value out of range: {token!r}")

    return value


def _parse_item(
    item: str, low: int, high: int, names: dict[str, int] | None
) -> set[int]:
    if not item:
        raise ValueError("empty item")

    if "/" in item:
        pieces = item.split("/")
        if len(pieces) != 2:
            raise ValueError(f"invalid item: {item!r}")
        base, step_text = pieces
        if _NUMBER_RE.fullmatch(step_text) is None:
            raise ValueError(f"invalid step: {item!r}")
        step = int(step_text)
        if step <= 0:
            raise ValueError(f"invalid step: {item!r}")
    else:
        base = item
        step = None

    if base == "*":
        start, end = low, high
    elif "-" in base:
        pieces = base.split("-")
        if len(pieces) != 2:
            raise ValueError(f"invalid item: {item!r}")
        start = _parse_value(pieces[0], low, high, names)
        end = _parse_value(pieces[1], low, high, names)
        if start > end:
            raise ValueError(f"invalid range: {item!r}")
    else:
        start = _parse_value(base, low, high, names)
        # A bare value with a step runs to the end of the field's range.
        end = high if step is not None else start

    if step is None:
        step = 1

    return set(range(start, end + 1, step))


def _parse_field(
    text: str, low: int, high: int, names: dict[str, int] | None = None
) -> set[int]:
    if not text:
        raise ValueError("empty field")

    values: set[int] = set()
    for item in text.split(","):
        values |= _parse_item(item, low, high, names)
    return values


def _day_matches(
    day: date,
    days_of_month: set[int],
    days_of_week: set[int],
    dom_restricted: bool,
    dow_restricted: bool,
) -> bool:
    dom_match = day.day in days_of_month
    dow_match = ((day.weekday() + 1) % 7) in days_of_week

    if dom_restricted and dow_restricted:
        return dom_match or dow_match
    return dom_match and dow_match


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError(f"invalid cron expression: {expression!r}")

    minutes = _parse_field(fields[0], 0, 59)
    hours = _parse_field(fields[1], 0, 23)
    days_of_month = _parse_field(fields[2], 1, 31)
    months = _parse_field(fields[3], 1, 12, _MONTH_NAMES)

    days_of_week = _parse_field(fields[4], 0, 7, _DAY_NAMES)
    days_of_week = {0 if value == 7 else value for value in days_of_week}

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = after + timedelta(days=365 * 5)

    day = start.date()
    last_day = limit.date()

    while day <= last_day:
        if day.month in months and _day_matches(
            day,
            days_of_month,
            days_of_week,
            dom_restricted,
            dow_restricted,
        ):
            if day == start.date():
                earliest = start
            else:
                earliest = datetime.combine(day, time(0, 0), after.tzinfo)

            for hour in sorted(hours):
                for minute in sorted(minutes):
                    candidate = datetime.combine(
                        day, time(hour, minute), after.tzinfo
                    )
                    if earliest <= candidate <= limit:
                        return candidate

        day += timedelta(days=1)

    raise ValueError(f"no run within five years: {expression!r}")

